insert into public.species (slug, name, latin, category_id, kind, difficulty, temperament, description, facts, keywords, care_notice, range_areas, name_note, status, content_updated_at)
select e->>'s', e->>'n', e->>'l', 'deniz-baliklari', 'fish', e->>'d', e->>'t', e->>'x',
 (select jsonb_agg(jsonb_build_array((array['Yetişkin boy','Sıcaklık','pH','Min. akvaryum','Huy','Beslenme','Üreme','Köken','Ömür','Özellikler'])[i], e->'f'->>(i-1)) order by i) from generate_series(1,10) i),
